package com.crypto.laplace.execution;
import static org.mockito.Mockito.*;import static org.assertj.core.api.Assertions.assertThat;import com.crypto.common.enums.PositionSide;import com.crypto.laplace.config.LaplaceStrategyProperties;import com.crypto.laplace.model.*;import com.crypto.laplace.persistence.*;import com.crypto.laplace.pool.*;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.BeforeEach;import org.junit.jupiter.api.Test;
class LaplacePaperTradeCoordinatorTest {
 LaplacePaperPositionRepository repo=mock(LaplacePaperPositionRepository.class);LaplacePaperExecutionService execution=mock(LaplacePaperExecutionService.class);LaplaceTradeJsonlWriter writer=mock(LaplaceTradeJsonlWriter.class);LaplaceStrategyProperties config=new LaplaceStrategyProperties();LaplacePaperTradeCoordinator coordinator;
 @BeforeEach void setup(){config.getLaplace().setPaperExecutionEnabled(true);coordinator=new LaplacePaperTradeCoordinator(config,repo,execution,writer);}
 @Test void mapsRawSignalsContrarian(){assertThat(coordinator.mapRawSignalToExecutionSide(LaplaceSignal.LONG)).isEqualTo(PositionSide.SHORT);assertThat(coordinator.mapRawSignalToExecutionSide(LaplaceSignal.SHORT)).isEqualTo(PositionSide.LONG);assertThat(coordinator.mapRawSignalToExecutionSide(LaplaceSignal.NONE)).isNull();}
 @Test void startupBaselineSameSignalDoesNotOpen(){coordinator.initializeBaseline("BTCUSDT",LaplaceSignal.LONG);coordinator.onSignal(signal(LaplaceSignal.LONG,LaplaceSignal.NONE,true),true);verifyNoInteractions(execution);}
 @Test void flatLongOpensExactlyOnce(){when(repo.findByStrategyAndSymbolAndStatus(any(),any(),any())).thenReturn(List.of());when(execution.open(any(),eq(PositionSide.LONG),eq(PositionSide.SHORT),isNull(),eq("FLAT"))).thenReturn(position(PositionSide.LONG));coordinator.initializeBaseline("BTCUSDT", LaplaceSignal.NONE);coordinator.onSignal(signal(LaplaceSignal.LONG,LaplaceSignal.NONE,true),true);verify(execution).open(any(),eq(PositionSide.LONG),eq(PositionSide.SHORT),isNull(),eq("FLAT"));}
 @Test void ineligibleSignalDoesNotOpen(){coordinator.initializeBaseline("BTCUSDT", LaplaceSignal.NONE);coordinator.onSignal(signal(LaplaceSignal.LONG,LaplaceSignal.NONE,false),true);verifyNoInteractions(execution);}
 @Test void paperDisabledDoesNotOpenOrWritePerSignalFailures(){config.getLaplace().setPaperExecutionEnabled(false);coordinator.initializeBaseline("BTCUSDT", LaplaceSignal.NONE);coordinator.onSignal(signal(LaplaceSignal.LONG,LaplaceSignal.NONE,true),true);coordinator.onSignal(signal(LaplaceSignal.SHORT,LaplaceSignal.NONE,true),true);verifyNoInteractions(execution,writer);}
 @Test void sameSideSignalDoesNotPyramid(){when(repo.findByStrategyAndSymbolAndStatus(any(),any(),any())).thenReturn(List.of(position(PositionSide.SHORT)));coordinator.initializeBaseline("BTCUSDT", LaplaceSignal.NONE);coordinator.onSignal(signal(LaplaceSignal.SHORT,LaplaceSignal.SHORT,true),true);verifyNoInteractions(execution);}
 @Test void strongOppositeReversesButNormalEntryDoesNot(){var p=position(PositionSide.LONG);when(repo.findByStrategyAndSymbolAndStatus(any(),any(),any())).thenReturn(List.of(p));coordinator.initializeBaseline("BTCUSDT", LaplaceSignal.NONE);coordinator.onSignal(signal(LaplaceSignal.LONG,LaplaceSignal.NONE,true),true);verifyNoInteractions(execution);coordinator.onSignal(signal(LaplaceSignal.SHORT,LaplaceSignal.SHORT,true),true);verify(execution).reverse(any(),eq(p),eq(PositionSide.SHORT),eq(PositionSide.LONG),eq(true));}
 @Test void outsideUniverseClosesWithoutOpeningTarget(){var p=position(PositionSide.LONG);when(repo.findByStrategyAndSymbolAndStatus(any(),any(),any())).thenReturn(List.of(p));coordinator.initializeBaseline("BTCUSDT", LaplaceSignal.NONE);coordinator.onSignal(signal(LaplaceSignal.SHORT,LaplaceSignal.SHORT,true),false);verify(execution).reverse(any(),eq(p),eq(PositionSide.SHORT),eq(PositionSide.LONG),eq(false));}
 @Test void stopLossWaitsForOppositeSignalBeforeOpeningAgain(){when(repo.findByStrategyAndSymbolAndStatus(any(),any(),any())).thenReturn(List.of());coordinator.onStopLossClosed("BTCUSDT","LONG","SHORT","position",Instant.now());coordinator.onSignal(signal(LaplaceSignal.LONG,LaplaceSignal.NONE,true),true);coordinator.onSignal(signal(LaplaceSignal.NONE,LaplaceSignal.NONE,false),true);coordinator.onSignal(signal(LaplaceSignal.LONG,LaplaceSignal.NONE,true),true);verifyNoInteractions(execution);coordinator.onSignal(signal(LaplaceSignal.SHORT,LaplaceSignal.NONE,true),true);verify(execution).open(any(),eq(PositionSide.SHORT),eq(PositionSide.LONG),isNull(),eq("FLAT"));}
 @Test void staleSnapshotDoesNotBlockWaitingToActiveLongEntryInSameCycle(){LaplaceCoinPoolService pool=mock(LaplaceCoinPoolService.class);coordinator=new LaplacePaperTradeCoordinator(config,repo,execution,writer,pool);when(pool.observeTrend("BTCUSDT",LaplaceTrend.LONG)).thenReturn(true);when(pool.allowAfterOppositeSignal(any(),any())).thenReturn(true);when(pool.isCurrentlyEligibleForEntry("BTCUSDT")).thenReturn(allowed());when(repo.findByStrategyAndSymbolAndStatus(any(),any(),any())).thenReturn(List.of());coordinator.initializeBaseline("BTCUSDT",LaplaceSignal.NONE);coordinator.onSignal(signal(LaplaceSignal.LONG,LaplaceSignal.NONE,true),false);verify(execution).open(any(),eq(PositionSide.LONG),eq(PositionSide.SHORT),isNull(),eq("FLAT"));verify(writer,never()).failure(any(),any(),any(),any(),eq("SYMBOL_OUTSIDE_ENTRY_UNIVERSE"),any(),anyBoolean());}
 @Test void staleSnapshotDoesNotBlockWaitingToActiveShortEntryAndContinuationDoesNotDuplicate(){LaplaceCoinPoolService pool=mock(LaplaceCoinPoolService.class);coordinator=new LaplacePaperTradeCoordinator(config,repo,execution,writer,pool);when(pool.observeTrend("BTCUSDT",LaplaceTrend.SHORT)).thenReturn(true);when(pool.allowAfterOppositeSignal(any(),any())).thenReturn(true);when(pool.isCurrentlyEligibleForEntry("BTCUSDT")).thenReturn(allowed());when(repo.findByStrategyAndSymbolAndStatus(any(),any(),any())).thenReturn(List.of());coordinator.initializeBaseline("BTCUSDT",LaplaceSignal.NONE);coordinator.onSignal(signal(LaplaceSignal.SHORT,LaplaceSignal.NONE,true),false);coordinator.onSignal(signal(LaplaceSignal.SHORT,LaplaceSignal.NONE,true),false);verify(execution,times(1)).open(any(),eq(PositionSide.SHORT),eq(PositionSide.LONG),isNull(),eq("FLAT"));}
 @Test void currentPoolHardBlockStillPreventsEntry(){LaplaceCoinPoolService pool=mock(LaplaceCoinPoolService.class);coordinator=new LaplacePaperTradeCoordinator(config,repo,execution,writer,pool);when(pool.observeTrend(any(),any())).thenReturn(true);when(pool.allowAfterOppositeSignal(any(),any())).thenReturn(true);when(pool.isCurrentlyEligibleForEntry("BTCUSDT")).thenReturn(new LaplaceCoinPoolService.EntryEligibility(false,LaplaceCoinPoolState.ACTIVE,true,true,0,"REENTRY_LOCK_ACTIVE",Instant.now()));when(repo.findByStrategyAndSymbolAndStatus(any(),any(),any())).thenReturn(List.of());coordinator.initializeBaseline("BTCUSDT",LaplaceSignal.NONE);coordinator.onSignal(signal(LaplaceSignal.LONG,LaplaceSignal.NONE,true),true);verifyNoInteractions(execution);verify(writer).failure(eq("BTCUSDT"),any(),eq("FLAT"),eq("ENTRY"),eq("REENTRY_LOCK_ACTIVE"),isNull(),eq(false),anyMap());}
 @Test void bookTickerFailureIsIsolatedAndPublishesDetailedFailure(){when(repo.findByStrategyAndSymbolAndStatus(any(),any(),any())).thenReturn(List.of());when(execution.open(any(),any(),any(),any(),any())).thenThrow(new IllegalStateException("BOOK_TICKER_UNAVAILABLE"));coordinator.initializeBaseline("BTCUSDT",LaplaceSignal.NONE);coordinator.onSignal(signal(LaplaceSignal.LONG,LaplaceSignal.NONE,true),true);verify(writer).failure(eq("BTCUSDT"),any(),eq("FLAT"),eq("ENTRY"),eq("BOOK_TICKER_UNAVAILABLE"),any(),eq(false),argThat(a->a.get("requestedSide")==PositionSide.LONG&&"ASK".equals(a.get("requestedExecutionPriceType"))));}
 @Test void riskyEntryCreatesNoPositionAndAddsNoCooldownWhileNextSafeSignalStillOpens(){when(repo.findByStrategyAndSymbolAndStatus(any(),any(),any())).thenReturn(List.of());coordinator.initializeBaseline("BTCUSDT",LaplaceSignal.NONE);coordinator.onSignal(signal(LaplaceSignal.LONG,LaplaceSignal.NONE,true,2.0,0.0),true);verifyNoInteractions(execution);coordinator.onSignal(signal(LaplaceSignal.NONE,LaplaceSignal.NONE,false,1.0,0.10),true);coordinator.onSignal(signal(LaplaceSignal.SHORT,LaplaceSignal.NONE,true,1.0,0.10),true);verify(execution).open(any(),eq(PositionSide.SHORT),eq(PositionSide.LONG),isNull(),eq("FLAT"));}
 @Test void riskyLongIsAuditedAsInvertedShortAndSafeLongRemainsBlocked(){when(repo.findByStrategyAndSymbolAndStatus(any(),any(),any())).thenReturn(List.of());coordinator.initializeBaseline("BTCUSDT",LaplaceSignal.NONE);coordinator.onSignal(signal(LaplaceSignal.LONG,LaplaceSignal.NONE,true,2.0,0.0),true);verify(writer).entrySkipped(any(),eq(PositionSide.SHORT),any());coordinator.onSignal(signal(LaplaceSignal.LONG,LaplaceSignal.NONE,true,1.9999,0.0),true);verifyNoInteractions(execution);verify(writer,times(1)).entrySkipped(any(),any(),any());}
 @Test void riskyShortIsAuditedAsInvertedLong(){when(repo.findByStrategyAndSymbolAndStatus(any(),any(),any())).thenReturn(List.of());coordinator.initializeBaseline("BTCUSDT",LaplaceSignal.NONE);coordinator.onSignal(signal(LaplaceSignal.SHORT,LaplaceSignal.NONE,true,2.0,0.0),true);verify(writer).entrySkipped(any(),eq(PositionSide.LONG),any());verifyNoInteractions(execution);}
 @Test void repeatedSafeLongCandlesRemainBlockedUntilDirectionChanges(){when(repo.findByStrategyAndSymbolAndStatus(any(),any(),any())).thenReturn(List.of());coordinator.initializeBaseline("BTCUSDT",LaplaceSignal.NONE);coordinator.onSignal(signal(LaplaceSignal.LONG,LaplaceSignal.NONE,true,2.0,0.0),true);for(int i=0;i<3;i++)coordinator.onSignal(signal(LaplaceSignal.LONG,LaplaceSignal.NONE,true,1.0,0.10),true);verifyNoInteractions(execution);verify(writer,times(1)).entrySkipped(any(),any(),any());}
 @Test void directionChangeClearsLongBlockAndOpensInvertedLongOnlyOnce(){when(repo.findByStrategyAndSymbolAndStatus(any(),any(),any())).thenReturn(List.of());coordinator.initializeBaseline("BTCUSDT",LaplaceSignal.NONE);coordinator.onSignal(signal(LaplaceSignal.LONG,LaplaceSignal.NONE,true,2.0,0.0),true);coordinator.onSignal(signal(LaplaceSignal.LONG,LaplaceSignal.NONE,true,1.0,0.10),true);coordinator.onSignal(signal(LaplaceSignal.SHORT,LaplaceSignal.NONE,true,1.0,0.10),true);coordinator.onSignal(signal(LaplaceSignal.SHORT,LaplaceSignal.NONE,true,1.0,0.10),true);verify(execution,times(1)).open(any(),eq(PositionSide.SHORT),eq(PositionSide.LONG),isNull(),eq("FLAT"));}
 @Test void riskyNewDirectionReplacesPreviousDirectionBlock(){LaplaceCoinPoolService pool=mock(LaplaceCoinPoolService.class);coordinator=new LaplacePaperTradeCoordinator(config,repo,execution,writer,pool);when(pool.observeTrend(any(),any())).thenReturn(true);when(pool.allowAfterOppositeSignal(any(),any())).thenReturn(true);when(pool.isCurrentlyEligibleForEntry(any())).thenReturn(allowed());when(repo.findByStrategyAndSymbolAndStatus(any(),any(),any())).thenReturn(List.of());coordinator.initializeBaseline("BTCUSDT",LaplaceSignal.NONE);coordinator.onSignal(signal(LaplaceSignal.LONG,LaplaceSignal.NONE,true,2.0,0.0),true);when(pool.hasRiskyDirectionBlock("BTCUSDT")).thenReturn(true);coordinator.onSignal(signal(LaplaceSignal.SHORT,LaplaceSignal.NONE,true,2.0,0.0),true);verify(pool).clearRiskyDirectionBlock("BTCUSDT");verify(pool).blockRiskyDirection(eq("BTCUSDT"),eq("SHORT"),any());verifyNoInteractions(execution);}
 @Test void persistedRiskyDirectionBlockSurvivesCoordinatorRecreation(){LaplaceCoinPoolService pool=mock(LaplaceCoinPoolService.class);when(pool.observeTrend(any(),any())).thenReturn(true);when(pool.allowAfterOppositeSignal(any(),any())).thenReturn(true);when(pool.isCurrentlyEligibleForEntry(any())).thenReturn(allowed());when(repo.findByStrategyAndSymbolAndStatus(any(),any(),any())).thenReturn(List.of());LaplacePaperTradeCoordinator first=new LaplacePaperTradeCoordinator(config,repo,execution,writer,pool);first.initializeBaseline("BTCUSDT",LaplaceSignal.NONE);first.onSignal(signal(LaplaceSignal.LONG,LaplaceSignal.NONE,true,2.0,0.0),true);verify(pool).blockRiskyDirection(eq("BTCUSDT"),eq("LONG"),any());when(pool.isRiskyDirectionBlocked("BTCUSDT","LONG")).thenReturn(true);LaplacePaperTradeCoordinator restarted=new LaplacePaperTradeCoordinator(config,repo,execution,writer,pool);restarted.initializeBaseline("BTCUSDT",LaplaceSignal.LONG);restarted.onSignal(signal(LaplaceSignal.LONG,LaplaceSignal.NONE,true,1.0,0.10),true);verifyNoInteractions(execution);verify(pool,never()).clearRiskyDirectionBlock("BTCUSDT");}
 @Test void riskyStrongReversalClosesWithoutReplacementAndSameRawDirectionStaysBlocked(){var p=position(PositionSide.SHORT);when(repo.findByStrategyAndSymbolAndStatus(any(),any(),any())).thenReturn(List.of(p),List.of(p),List.of(),List.of());coordinator.initializeBaseline("BTCUSDT",LaplaceSignal.NONE);coordinator.onSignal(signal(LaplaceSignal.LONG,LaplaceSignal.LONG,true,2.0,0.0),true);verify(execution).reverse(any(),eq(p),eq(PositionSide.LONG),eq(PositionSide.SHORT),eq(false));coordinator.onSignal(signal(LaplaceSignal.LONG,LaplaceSignal.LONG,true,1.0,0.10),true);verify(execution,never()).open(any(),any(),any(),any(),any());}
 @Test void volumeProfileRejectionDoesNotConsumeRawSignalOrCreatePersistentBlock(){LaplaceVolumeProfileService vp=mock(LaplaceVolumeProfileService.class);LaplaceEntryDecisionService entries=new LaplaceEntryDecisionService(new LaplaceRiskyEntryFilter());coordinator=new LaplacePaperTradeCoordinator(config,repo,execution,writer,null,entries,vp);when(repo.findByStrategyAndSymbolAndStatus(any(),any(),any())).thenReturn(List.of());when(vp.evaluate(any(),any(),anyDouble(),any())).thenReturn(vpRejected());coordinator.initializeBaseline("BTCUSDT",LaplaceSignal.NONE);coordinator.onSignal(signal(LaplaceSignal.LONG,LaplaceSignal.NONE,true),true);coordinator.onSignal(signal(LaplaceSignal.LONG,LaplaceSignal.NONE,true),true);verify(vp,times(2)).evaluate(any(),any(),anyDouble(),eq(PositionSide.SHORT));verifyNoInteractions(execution);verify(writer,never()).entrySkipped(any(),any(),any());}
 @Test void invertedRawLongFiltersAsShortButExecutesLong(){LaplaceVolumeProfileService vp=mock(LaplaceVolumeProfileService.class);coordinator=new LaplacePaperTradeCoordinator(config,repo,execution,writer,null,new LaplaceEntryDecisionService(new LaplaceRiskyEntryFilter()),vp);when(repo.findByStrategyAndSymbolAndStatus(any(),any(),any())).thenReturn(List.of());when(vp.evaluate(any(),any(),anyDouble(),eq(PositionSide.SHORT))).thenReturn(vpAllowed());coordinator.initializeBaseline("BTCUSDT",LaplaceSignal.NONE);coordinator.onSignal(signal(LaplaceSignal.LONG,LaplaceSignal.NONE,true),true);verify(vp).evaluate(any(),any(),anyDouble(),eq(PositionSide.SHORT));verify(execution).open(any(),eq(PositionSide.LONG),eq(PositionSide.SHORT),isNull(),eq("FLAT"));}
 @Test void invertedRawShortFiltersAsLongButExecutesShort(){LaplaceVolumeProfileService vp=mock(LaplaceVolumeProfileService.class);coordinator=new LaplacePaperTradeCoordinator(config,repo,execution,writer,null,new LaplaceEntryDecisionService(new LaplaceRiskyEntryFilter()),vp);when(repo.findByStrategyAndSymbolAndStatus(any(),any(),any())).thenReturn(List.of());when(vp.evaluate(any(),any(),anyDouble(),eq(PositionSide.LONG))).thenReturn(vpAllowed());coordinator.initializeBaseline("BTCUSDT",LaplaceSignal.NONE);coordinator.onSignal(signal(LaplaceSignal.SHORT,LaplaceSignal.NONE,true),true);verify(vp).evaluate(any(),any(),anyDouble(),eq(PositionSide.LONG));verify(execution).open(any(),eq(PositionSide.SHORT),eq(PositionSide.LONG),isNull(),eq("FLAT"));}
 @Test void outsideEntryUniverseDoesNotCalculateVolumeProfile(){LaplaceCoinPoolService pool=mock(LaplaceCoinPoolService.class);LaplaceVolumeProfileService vp=mock(LaplaceVolumeProfileService.class);coordinator=new LaplacePaperTradeCoordinator(config,repo,execution,writer,pool,new LaplaceEntryDecisionService(new LaplaceRiskyEntryFilter()),vp);when(pool.observeTrend(any(),any())).thenReturn(true);when(pool.isCurrentlyEligibleForEntry("BTCUSDT")).thenReturn(new LaplaceCoinPoolService.EntryEligibility(false,LaplaceCoinPoolState.REMOVED,false,false,0,"SYMBOL_OUTSIDE_ENTRY_UNIVERSE",Instant.now()));when(repo.findByStrategyAndSymbolAndStatus(any(),any(),any())).thenReturn(List.of());coordinator.initializeBaseline("BTCUSDT",LaplaceSignal.NONE);coordinator.onSignal(signal(LaplaceSignal.LONG,LaplaceSignal.NONE,true),false);verifyNoInteractions(vp,execution);}
 @Test void pendingOrFailedWarmupBlocksOnlyNewEntries(){for(Kural3WarmupStatus status:List.of(Kural3WarmupStatus.PENDING,Kural3WarmupStatus.FAILED)){reset(repo,execution);Kural3WarmupService warmup=mock(Kural3WarmupService.class);when(warmup.status("BTCUSDT")).thenReturn(status);coordinator=new LaplacePaperTradeCoordinator(config,repo,execution,writer,null,new LaplaceEntryDecisionService(new LaplaceRiskyEntryFilter()),mock(LaplaceVolumeProfileService.class),warmup);when(repo.findByStrategyAndSymbolAndStatus(any(),any(),any())).thenReturn(List.of());coordinator.initializeBaseline("BTCUSDT",LaplaceSignal.NONE);coordinator.onSignal(signal(LaplaceSignal.LONG,LaplaceSignal.NONE,true),true);verifyNoInteractions(execution);}}
 @Test void reversalReplacementDoesNotInvokeFlatEntryVolumeProfileGate(){LaplaceVolumeProfileService vp=mock(LaplaceVolumeProfileService.class);var open=position(PositionSide.LONG);when(repo.findByStrategyAndSymbolAndStatus(any(),any(),any())).thenReturn(List.of(open));coordinator=new LaplacePaperTradeCoordinator(config,repo,execution,writer,null,new LaplaceEntryDecisionService(new LaplaceRiskyEntryFilter()),vp);coordinator.initializeBaseline("BTCUSDT",LaplaceSignal.NONE);coordinator.onSignal(signal(LaplaceSignal.SHORT,LaplaceSignal.SHORT,true),true);verifyNoInteractions(vp);verify(execution).reverse(any(),eq(open),eq(PositionSide.SHORT),eq(PositionSide.LONG),eq(true));}
 @Test void failedWarmupDoesNotBlockExistingPositionReversalOrReplacement(){Kural3WarmupService warmup=mock(Kural3WarmupService.class);when(warmup.status(any())).thenReturn(Kural3WarmupStatus.FAILED);var open=position(PositionSide.LONG);when(repo.findByStrategyAndSymbolAndStatus(any(),any(),any())).thenReturn(List.of(open));coordinator=new LaplacePaperTradeCoordinator(config,repo,execution,writer,null,new LaplaceEntryDecisionService(new LaplaceRiskyEntryFilter()),mock(LaplaceVolumeProfileService.class),warmup);coordinator.initializeBaseline("BTCUSDT",LaplaceSignal.NONE);coordinator.onSignal(signal(LaplaceSignal.SHORT,LaplaceSignal.SHORT,true),true);verify(execution).reverse(any(),eq(open),eq(PositionSide.SHORT),eq(PositionSide.LONG),eq(true));}
 @Test void kural4RawOpensRawSideAfterLegacyVp(){LaplaceVolumeProfileService vp=mock(LaplaceVolumeProfileService.class);Kural4MarketContextService contexts=mock(Kural4MarketContextService.class);Kural4ExecutionDecisionService overlays=mock(Kural4ExecutionDecisionService.class);coordinator=new LaplacePaperTradeCoordinator(config,repo,execution,writer,null,new LaplaceEntryDecisionService(new LaplaceRiskyEntryFilter()),vp,null,contexts,overlays);when(repo.findByStrategyAndSymbolAndStatus(any(),any(),any())).thenReturn(List.of());when(vp.evaluate(any(),any(),anyDouble(),eq(PositionSide.SHORT))).thenReturn(vpAllowed());var c=context();when(contexts.contextAt(any())).thenReturn(c);when(overlays.decide(any(),any(),eq(c))).thenReturn(overlay(PositionSide.LONG,PositionSide.LONG,Kural4ExecutionAction.RAW,List.of(),c));coordinator.initializeBaseline("BTCUSDT",LaplaceSignal.NONE);coordinator.onSignal(signal(LaplaceSignal.LONG,LaplaceSignal.NONE,true),true);verify(execution).openWithOverlay(any(),eq(PositionSide.LONG),argThat(a->a.rawExecutionSide()==PositionSide.LONG&&a.volumeProfileFilteringSide()==PositionSide.SHORT),isNull(),eq("FLAT"));}
 @Test void kural4InvertedOpensFinalSide(){LaplaceVolumeProfileService vp=mock(LaplaceVolumeProfileService.class);Kural4MarketContextService contexts=mock(Kural4MarketContextService.class);Kural4ExecutionDecisionService overlays=mock(Kural4ExecutionDecisionService.class);coordinator=new LaplacePaperTradeCoordinator(config,repo,execution,writer,null,new LaplaceEntryDecisionService(new LaplaceRiskyEntryFilter()),vp,null,contexts,overlays);when(repo.findByStrategyAndSymbolAndStatus(any(),any(),any())).thenReturn(List.of());when(vp.evaluate(any(),any(),anyDouble(),any())).thenReturn(vpAllowed());var c=context();when(contexts.contextAt(any())).thenReturn(c);when(overlays.decide(any(),any(),any())).thenReturn(overlay(PositionSide.LONG,PositionSide.SHORT,Kural4ExecutionAction.INVERTED,List.of(Kural4DecisionReason.K4_INVERT_RAW_LONG),c));coordinator.initializeBaseline("BTCUSDT",LaplaceSignal.NONE);coordinator.onSignal(signal(LaplaceSignal.LONG,LaplaceSignal.NONE,true),true);verify(execution).openWithOverlay(any(),eq(PositionSide.SHORT),any(LaplaceExecutionOverlayContext.class),isNull(),eq("FLAT"));}
 @Test void strategicSkipDoesNotOpenOrPersistentlyBlockDirection(){LaplaceCoinPoolService pool=mock(LaplaceCoinPoolService.class);LaplaceVolumeProfileService vp=mock(LaplaceVolumeProfileService.class);Kural4MarketContextService contexts=mock(Kural4MarketContextService.class);Kural4ExecutionDecisionService overlays=mock(Kural4ExecutionDecisionService.class);coordinator=new LaplacePaperTradeCoordinator(config,repo,execution,writer,pool,new LaplaceEntryDecisionService(new LaplaceRiskyEntryFilter()),vp,null,contexts,overlays);when(pool.observeTrend(any(),any())).thenReturn(true);when(pool.allowAfterOppositeSignal(any(),any())).thenReturn(true);when(pool.isCurrentlyEligibleForEntry(any())).thenReturn(allowed());when(repo.findByStrategyAndSymbolAndStatus(any(),any(),any())).thenReturn(List.of());when(vp.evaluate(any(),any(),anyDouble(),any())).thenReturn(vpAllowed());var c=context();when(contexts.contextAt(any())).thenReturn(c);when(overlays.decide(any(),any(),any())).thenReturn(new Kural4ExecutionDecision(false,PositionSide.SHORT,null,Kural4ExecutionAction.SKIP,List.of(Kural4DecisionReason.EXT_B_SKIP_RAW_SHORT),c));coordinator.initializeBaseline("BTCUSDT",LaplaceSignal.NONE);coordinator.onSignal(signal(LaplaceSignal.SHORT,LaplaceSignal.NONE,true),true);verifyNoInteractions(execution);verify(pool,never()).blockRiskyDirection(any(),any(),any());verify(writer).kural4EntrySkipped(any(),eq(PositionSide.SHORT),eq(PositionSide.LONG),any(),any());}
 @Test void unavailableContextRestoresRawStateAndAllowsRetry(){LaplaceVolumeProfileService vp=mock(LaplaceVolumeProfileService.class);Kural4MarketContextService contexts=mock(Kural4MarketContextService.class);Kural4ExecutionDecisionService overlays=mock(Kural4ExecutionDecisionService.class);coordinator=new LaplacePaperTradeCoordinator(config,repo,execution,writer,null,new LaplaceEntryDecisionService(new LaplaceRiskyEntryFilter()),vp,null,contexts,overlays);when(repo.findByStrategyAndSymbolAndStatus(any(),any(),any())).thenReturn(List.of());when(vp.evaluate(any(),any(),anyDouble(),any())).thenReturn(vpAllowed());when(contexts.contextAt(any())).thenReturn(null);when(overlays.decide(any(),any(),isNull())).thenReturn(new Kural4ExecutionDecision(false,PositionSide.LONG,null,Kural4ExecutionAction.SKIP,List.of(Kural4DecisionReason.MARKET_CONTEXT_UNAVAILABLE),null));coordinator.initializeBaseline("BTCUSDT",LaplaceSignal.NONE);var signal=signal(LaplaceSignal.LONG,LaplaceSignal.NONE,true);coordinator.onSignal(signal,true);coordinator.onSignal(signal,true);verify(contexts,times(2)).contextAt(signal.signalCandleCloseTime());verifyNoInteractions(execution);}
 @Test void reversalSkipClosesWithoutReplacementAndAuditsOverlay(){LaplaceVolumeProfileService vp=mock(LaplaceVolumeProfileService.class);Kural4MarketContextService contexts=mock(Kural4MarketContextService.class);Kural4ExecutionDecisionService overlays=mock(Kural4ExecutionDecisionService.class);var open=position(PositionSide.LONG);coordinator=new LaplacePaperTradeCoordinator(config,repo,execution,writer,null,new LaplaceEntryDecisionService(new LaplaceRiskyEntryFilter()),vp,null,contexts,overlays);when(repo.findByStrategyAndSymbolAndStatus(any(),any(),any())).thenReturn(List.of(open));when(vp.evaluate(any(),any(),anyDouble(),eq(PositionSide.LONG))).thenReturn(vpAllowed());var c=context();when(contexts.contextAt(any())).thenReturn(c);var skipped=new Kural4ExecutionDecision(false,PositionSide.SHORT,null,Kural4ExecutionAction.SKIP,List.of(Kural4DecisionReason.EXT_B_SKIP_RAW_SHORT),c);when(overlays.decide(any(),any(),any())).thenReturn(skipped);coordinator.initializeBaseline("BTCUSDT",LaplaceSignal.NONE);coordinator.onSignal(signal(LaplaceSignal.SHORT,LaplaceSignal.SHORT,true),true);verify(execution).reverseWithOverlay(any(),eq(open),eq(PositionSide.SHORT),argThat(a->a.kural4Decision()==skipped&&a.rawExecutionSide()==PositionSide.SHORT),eq(false));verify(writer).kural4EntrySkipped(any(),eq(PositionSide.SHORT),eq(PositionSide.LONG),eq(skipped),any());}
 private Kural4MarketContext context(){Instant t=Instant.now();return new Kural4MarketContext(t,t,100,.1,.1,.5,20);}
 private Kural4ExecutionDecision overlay(PositionSide raw,PositionSide side,Kural4ExecutionAction action,List<Kural4DecisionReason> reasons,Kural4MarketContext c){return new Kural4ExecutionDecision(true,raw,side,action,reasons,c);}
 private LaplaceCoinPoolService.EntryEligibility allowed(){return new LaplaceCoinPoolService.EntryEligibility(true,LaplaceCoinPoolState.ACTIVE,true,false,0,null,Instant.now());}
 private LaplaceVolumeProfileDecision vpRejected(){return new LaplaceVolumeProfileDecision(java.time.LocalDate.now(),Instant.now(),Instant.now(),90,110,100,12,100,true,.2,null,false,false,false,false,false,VolumeProfileRejectionReason.VP_INSIDE_SHORT_BELOW_POC);}
 private LaplaceVolumeProfileDecision vpAllowed(){return new LaplaceVolumeProfileDecision(java.time.LocalDate.now(),Instant.now(),Instant.now(),90,110,100,12,100,true,0d,null,true,true,false,false,true,null);}
 private LaplacePaperPositionEntity position(PositionSide side){return LaplacePaperPositionEntity.builder().id("id").symbol("BTCUSDT").side(side).strategy(LaplacePaperExecutionService.STRATEGY).status(LaplacePositionStatus.OPEN).build();}
 private LaplaceSignalResult signal(LaplaceSignal entry,LaplaceSignal reversal,boolean eligible){Instant now=Instant.now();return new LaplaceSignalResult(LaplacePaperExecutionService.STRATEGY,"1.0","BTCUSDT","30m","LAPLACE",14,"CLOSE",false,now.minusSeconds(1800),now,100,99,98,97,1,1,10,10,1.0,.10,.1,.1,.03,.04,2,entry,reversal,StartupState.ACTIVE,1,eligible,List.of());}
 private LaplaceSignalResult signal(LaplaceSignal entry,LaplaceSignal reversal,boolean eligible,double atrPercentage,double imbalance){Instant now=Instant.now();return new LaplaceSignalResult(LaplacePaperExecutionService.STRATEGY,"1.0","BTCUSDT","30m","LAPLACE",14,"CLOSE",false,now.minusSeconds(1800),now,100,99,98,97,1,1,10,10,atrPercentage,imbalance,.1,.1,.03,.04,2,entry,reversal,StartupState.ACTIVE,1,eligible,List.of());}
}
